"""Freeze stage and actual retrieval assets before any E2 API call."""
from .common import *
from .bootstrap_runtime import build_e2,seal
from concurrent.futures import ThreadPoolExecutor

def main():
 d=P/'e2_bootstrap'
 write(d/'SCHEDULE.json',build_e2())
 write(d/'RUBRIC.md','''# E2/E2B frozen semantic review\n\nSingle familiar reviewer; primary opportunity review sees Q, fixed parent, current Claims, query and only returned top-five visible title/preview windows. It does not import full source contents or future Claims into a primary label. Mask arm and case identifiers in review packets; query wording may reveal the arm. Archive rationales and supporting refs for all gains. Commit judgments before aggregate. No Writer runs: claim admission is not measured, only an independently reviewed opportunity.\n\nNewMaterial: a new explicitly supported parent-relevant fact which could be a Verified Claim (including a useful binding), not completion of all parent constraints. Binding: a new concrete entity/event/document/relation anchor that reduces parent uncertainty. Direct: new evidence about a parent predicate/constraint, even a partial predicate; bridge: an identified intermediate anchor with a supported route to testing the parent, not mere topical similarity. These may overlap within one query. NoGain means neither material nor binding; unavailable slots are failures and are not real NoGain for escalation. Metrics retain all planned slots. Explicitly distinguish potential candidate from established target.\n\nDo not count an arbitrary member of a vast generic topic as progress. A source must share a discriminative parent facet, or establish a specific entity/date/relation relevant to reducing the current uncertainty. One conjunction facet can qualify even though other prerequisites remain. Current Claim repetition alone does not count. Direct and bridge evidence must be supported in visible raw text. Repeated-doc fraction uses returned slots as denominator and current-prefix corpus IDs; expose overlap across paired arms separately. Repeated documents can contain new evidence.\n\nQuery drift: incompatible entity/role/relation/time substitution or an objective outside parent scope, not every missing search keyword. Commitment: inserting an unsupported concrete candidate or asserting the identity/binding of a provisional candidate. Query-generation fidelity uses supplied objective as authority per TASK33; Q provides context but does not license adding an absent concrete name/date.\n\nE2B only actual P1 NoGain with both no material and no binding, accessible source unchanged, and an untried source-anchored parent facet. One extra objective and one extra query; schema failures block dependents, no repair. Oracle diagnostics remain separate, frozen before execution. No evidence-recognition failure can be claimed without an observed failed recognizer; this experiment has no Writer.\n''')
 code=[*sorted((ROOT/'llm_chat').glob('*.py')),ROOT/'BCPlus/scripts/search_bcplus.py',ROOT/'experiments/deferred_recovery/tools.py',ROOT/'experiments/evidence_scope_localization/runtime.py']
 prior=read(ROOT/'experiments/belief_need_budget_locality_repair/acquisition/FREEZE.json')['binary_files']
 files=[Path(x) for x in prior]+[p for p in Path('/data/model/Qwen3-Embedding-8B').glob('*') if p.is_file() and p.suffix in ['.json','.txt','.model']]
 def one(p):
  s=p.stat();return str(p),{'size':s.st_size,'mtime_ns':s.st_mtime_ns,'sha256':sha(p)}
 with ThreadPoolExecutor(max_workers=4) as pool:assets=dict(pool.map(one,files))
 write(d/'BACKEND.json',{'baseline':'Historical acquisition SearchFindTools v3a (same natural states), not the top50 diagnostic or orthogonal alternative','model':'Qwen3-Embedding-8B','embedding_dtype':'float16','device':'cuda:1','index':'original 100195-document IndexFlatIP4096 over sorted vector shards','k':5,'preview_budget_tokens':400,'title_budget_tokens':48,'ranking':'unchanged BCPlusSearcher.search','preview':'unchanged RawWindowBuilder.search, including query-localized window','parallelism':'4 isolated tokenizer/db/registry workers; shared embedding forward lock; API concurrency8','code_sha256':{rel(p):sha(p) for p in code},'assets':assets})
 seal('e2_bootstrap',extra=[P/'e1_residualization/METRICS.json',*[P/j['source']['path'].split('experiments/state_conditioned_residualization/')[1] for j in build_e2() if j['source']]])
 print('E2 freeze:22 slots,20 requests,11 accessible,6 qids')
if __name__=='__main__':main()
